import{_ as t,c as n,j as e,a as l,o as r}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第九十九章 二、三滴海水多吗？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/99第九十九章 二、三滴海水多吗.md","filePath":"meditation/巴利文大藏经/99第九十九章 二、三滴海水多吗.md"}'),o={name:"meditation/巴利文大藏经/99第九十九章 二、三滴海水多吗.md"};function _(s,a,i,d,p,c){return r(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第九十九章-二、三滴海水多吗",tabindex:"-1"},[l("第九十九章 二、三滴海水多吗？ "),e("a",{class:"header-anchor",href:"#第九十九章-二、三滴海水多吗","aria-label":'Permalink to "第九十九章 二、三滴海水多吗？"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部13相应8经/海洋经第二(现观相应/因缘篇/如来记说)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，如果从大海中取出二、三滴水保存下来，其余的大海水全部都干涸、干枯了，弟子们你们现在是怎么想的？是保存下来的二、三滴水更多，还是大海里已经全部干涸、干枯的水更多？”",-1),e("p",null,"出家弟子们回答：“世尊，当然是大海里全部干涸、干枯的水更多，保存下来的二、三滴水更少。大海里已经全部干涸、干枯的水是保存下来二、三滴水的百倍、千倍、十万倍、无数倍。保存下来的二、三滴水与大海里已经全部干涸、干枯的水相比可以忽略不计。”",-1),e("p",null,"佛陀说：“同样的道理，弟子们，具足正确见解，已经证悟初果（初果解释，见第七十章）及以上果位的圣弟子们，他们灭尽、灭除的烦恼和痛苦很多，他们灭尽的烦恼和痛苦就如同大海里已经全部干涸、干枯的水那样多，他们残留的烦恼和痛苦非常的少，他们残留的烦恼和痛苦就如同保存下来的二、三滴水那样少。弟子们，也就是说已经证悟初果的圣弟子们，他们残留的烦恼和痛苦比不上他们灭尽烦恼和痛苦的百分之一、千分之一、十万分之一，他们残留的烦恼和痛苦与他们灭尽的烦恼和痛苦相比可以忽略不计。这些已经证悟初果的圣弟子们，他们最多在人间和天界往返七次，就能永远的从生死轮回中解脱出来，也就是说已经证悟初果的圣弟子们，他们最多再有七次的生死轮回，就能除灭一切的烦恼和痛苦，就能从这个世间永远的解脱出来，就能从生死轮回中永远的解脱出来。弟子们，具足正确的见解，证悟初果就能获得这么大的功德利益，明白了如来所说的正法，就能获得这么大的功德利益。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(o,[["render",_]]);export{u as __pageData,f as default};
